use trustkit_cli::wave_board_cli_commands::{WaveBoardAction, WaveBoardCliResponse};

#[test]
fn test_task_003_red_phase_contract() {
    // Criterios: "Comandos CLI Wave Board Up Down Status e Paridade com Alias tk"
    let response = WaveBoardCliResponse::new(
        WaveBoardAction::Up,
        9876,
        8080,
        "http://127.0.0.1:8080",
        "Daemon started successfully",
        vec!["Open browser at http://127.0.0.1:8080".to_string()],
    );

    assert_eq!(response.status, "PASS");
    assert_eq!(response.action, "up");
    assert_eq!(response.pid, 9876);
    assert_eq!(response.port, 8080);

    let json = response.to_json_output();
    assert!(json.contains("\"status\": \"PASS\""));
    assert!(json.contains("\"port\": 8080"));

    let tty = response.to_tty_output();
    assert!(tty.contains("[PASS] Wave Board UP: Daemon started successfully"));
    assert!(tty.contains("NEXT STEP:"));

    assert!(true, "GREEN verified");
}
